INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
VALUES
('projetos.oportunidades.contador', 'Funil', 'Total de oportunidades',
 'Nada a preencher: é a contagem de todas as oportunidades da empresa (as excluídas não entram).',
 'Mostra que nada sumiu: total = em aberto + ganhas + perdidas. Serve para conferir com o que a equipe lançou.', '14 oportunidades · 8 em aberto · 4 ganhas · 2 perdidas', 'Comparar só o "em aberto" com o que foi lançado e achar que faltam cards — as ganhas e perdidas saem do funil ativo.', 100, '/dashboard/projetos/oportunidades', 'projetos', 'publicado'),
('projetos.oportunidades.nova', 'Funil', 'Nova oportunidade',
 'Abre o cadastro: cliente, serviço, valor estimado, etapa e responsável.',
 'Toda obra começa aqui: a oportunidade vira visita, orçamento e, quando ganha, obra.', 'Cliente pediu orçamento de piso para galpão de 1.200 m²', 'Criar outra oportunidade para o mesmo pedido em vez de mover a que já existe.', 110, '/dashboard/projetos/oportunidades', 'projetos', 'publicado'),
('projetos.oportunidades.kpi_aberto', 'Indicadores', 'Em aberto',
 'Nada a preencher: conta as oportunidades que ainda não foram ganhas nem perdidas.',
 'É o funil ativo — o que a equipe comercial ainda precisa trabalhar.', '8', 'Esperar que bata com o total: ganhas e perdidas ficam fora deste número.', 120, '/dashboard/projetos/oportunidades', 'projetos', 'publicado'),
('projetos.oportunidades.kpi_ganhas_mes', 'Indicadores', 'Ganhas no mês',
 'Nada a preencher: conta as oportunidades marcadas como ganhas com data de fechamento no mês atual.',
 'Mede o fechamento do mês corrente. Para ver todas as ganhas, clique no resumo "Ganhas".', '3 ganhas em outubro', 'Achar que o número zerou por erro no começo do mês — ele recomeça a cada mês.', 130, '/dashboard/projetos/oportunidades', 'projetos', 'publicado'),
('projetos.oportunidades.kpi_pipeline', 'Indicadores', 'Pipeline (R$)',
 'Nada a preencher: é a soma do valor estimado das oportunidades em aberto.',
 'Mostra quanto dinheiro está em negociação. Ganhas e perdidas não entram.', 'R$ 485.000,00', 'Deixar o valor estimado em branco no cadastro: a oportunidade conta como R$ 0 aqui.', 140, '/dashboard/projetos/oportunidades', 'projetos', 'publicado'),
('projetos.oportunidades.contagem_filtro', 'Funil', 'Oportunidades no filtro',
 'Nada a preencher: quantas oportunidades aparecem no funil com os filtros de etapa, responsável e busca escolhidos.',
 'Confere o tamanho da lista que você está vendo agora.', '5 oportunidade(s)', 'Esquecer um filtro ligado e achar que as outras sumiram.', 150, '/dashboard/projetos/oportunidades', 'projetos', 'publicado'),
('projetos.oportunidades.resumo_ganhas', 'Funil', 'Ganhas',
 'Clique para ver a lista das oportunidades ganhas, com valor e data.',
 'Quantidade e soma do valor de tudo que já foi ganho. A ganha é o ponto de partida da obra.', '4 · R$ 312.000,00', 'Procurar a oportunidade ganha nas colunas do funil — ela fica neste resumo.', 160, '/dashboard/projetos/oportunidades', 'projetos', 'publicado'),
('projetos.oportunidades.resumo_perdidas', 'Funil', 'Perdidas',
 'Clique para ver a lista das oportunidades perdidas e o motivo registrado.',
